func TestPpArithmeticRequiresASourceRuleAboveItsTotal(emonT *testing.T) {
	var rules *port.Cells = port.NewCells()
	var words *port.Cells = port.NewCells()
	var w int32 = evidence.OwNew(words, 1, 1000, 2000, 1500, 2200, 0, 0, 0, 0, 0, 0, 0, 3, 0, 900, -1)
	port.AssertEq(emonT, oapp.PpTotalRule(rules, words, 1, w), 0, "prose has no total rule")
	var otherPage int32 = evidence.RlNew(rules, 2, 900, 1900, 1600, 1950, 0)
	evidence.RlSet(rules, otherPage, evidence.RlfConf(), 1000)
	port.AssertEq(emonT, oapp.PpTotalRule(rules, words, 1, w), 0, "another page supplies no rule")
	var shortRule int32 = evidence.RlNew(rules, 1, 1100, 1900, 1400, 1950, 0)
	evidence.RlSet(rules, shortRule, evidence.RlfConf(), 1000)
	port.AssertEq(emonT, oapp.PpTotalRule(rules, words, 1, w), 0, "a short stroke does not span the total")
	var totalRule int32 = evidence.RlNew(rules, 1, 900, 1900, 1600, 1950, 0)
	evidence.RlSet(rules, totalRule, evidence.RlfConf(), 1000)
	port.AssertEq(emonT, oapp.PpTotalRule(rules, words, 1, w), 1, "source rule spans the total")
}
